(4506995, 648512, 39679, '<td valign="top">Very cool shot and its particularly cool that your leading lines all tend to converge on the center of your subject.  Nice job</td>', 'Very cool shot and its particularly cool that your leading lines all tend to converge on the center of your subject.  Nice job', '2008-02-22 11:16:35.000000', NULL, 1),
(4507001, 648615, 33233, '<td valign="top">Nice composition. I love the frost.</td>', 'Nice composition. I love the frost.', '2008-02-22 11:17:54.000000', NULL, 1),
(4507004, 648223, 33233, '<td valign="top">This is what "leading" lines are about. Leading to something. This is good.</td>', 'This is what "leading" lines are about. Leading to something. This is good.', '2008-02-22 11:18:28.000000', NULL, 1),
(4507008, 648779, 39679, '<td valign="top">this is a beautiful shot...really stunning.  However, I''m not getting a strong feeling for the challenge from it (though as I look at it the clouds do seem to be playing the part of "leading lines" in that they seem to be moving away from your subject).  In any case, this is certainly a shot to be proud of.</td>', 'this is a beautiful shot...really stunning.  However, I''m not getting a strong feeling for the challenge from it (though as I look at it the clouds do seem to be playing the part of "leading lines" in that they seem to be moving away from your subject).  In any case, this is certainly a shot to be proud of.', '2008-02-22 11:19:21.000000', NULL, 1),
(4507009, 648233, 33233, '<td valign="top">The perspective and "leading line" makes what would otherwise be a relatively uninteresting subject a good photo.</td>', 'The perspective and "leading line" makes what would otherwise be a relatively uninteresting subject a good photo.', '2008-02-22 11:19:34.000000', NULL, 1),
(4507012, 647966, 33233, '<td valign="top">Great shot. The in flight subject of the leading line is great.</td>', 'Great shot. The in flight subject of the leading line is great.', '2008-02-22 11:20:06.000000', NULL, 1),
(4507014, 648512, 33233, '<td valign="top">The ball changing the perspective on the lines give it the subject for the leading lines. Great shot.</td>', 'The ball changing the perspective on the lines give it the subject for the leading lines. Great shot.', '2008-02-22 11:20:56.000000', NULL, 1),
(4507019, 648054, 39679, '<td valign="top">What a wonderful shot!  Very creative and very interesting...fun to look at.  I love that it''s the convergence of the "strong" lines that you use as your leading lines.</td>', 'What a wonderful shot!  Very creative and very interesting...fun to look at.  I love that it''s the convergence of the "strong" lines that you use as your leading lines.', '2008-02-22 11:21:55.000000', NULL, 1),
(4507023, 647460, 33233, '<td valign="top">The detail texture of the bridge works as a subject for the leading lines. Good shot.</td>', 'The detail texture of the bridge works as a subject for the leading lines. Good shot.', '2008-02-22 11:23:16.000000', NULL, 1),
