(4507436, 648881, 88204, '<td valign="top">Great take on this. I love it that the leading lines are in the ceiling. I also like how the lines lead me to a human who will continue walking away... nice flow. Nice lighting in that the person is walking to a brighter space... that attracts my eye. Well done.</td>', 'Great take on this. I love it that the leading lines are in the ceiling. I also like how the lines lead me to a human who will continue walking away... nice flow. Nice lighting in that the person is walking to a brighter space... that attracts my eye. Well done.', '2008-02-22 13:42:58.000000', NULL, 1),
(4507437, 648110, 88204, '<td valign="top">Lines are subtle but effective.</td>', 'Lines are subtle but effective.', '2008-02-22 13:43:24.000000', NULL, 1),
(4507438, 648145, 88699, '<td valign="top">Oh, I get it!</td>', 'Oh, I get it!', '2008-02-22 13:43:39.000000', NULL, 1),
