(4507442, 648065, 88204, '<td valign="top">Great leading lines and nice use of selective color. It starts to feel a little beyond basic editing but if you get by, great shot!</td>', 'Great leading lines and nice use of selective color. It starts to feel a little beyond basic editing but if you get by, great shot!', '2008-02-22 13:45:38.000000', NULL, 1),
(4507448, 648562, 88204, '<td valign="top">The lines lead me in but there isn''t a subject at the end... leaves me wondering what I''m supposed to look at.</td>', 'The lines lead me in but there isn''t a subject at the end... leaves me wondering what I''m supposed to look at.', '2008-02-22 13:47:09.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4507452, 648512, 88204, '<td valign="top">Nice lines, lighting and reflections, although I''d like the lines to lead me to something.</td>', 'Nice lines, lighting and reflections, although I''d like the lines to lead me to something.', '2008-02-22 13:48:31.000000', NULL, 1),
