(4508990, 648877, 90380, '<td valign="top">I like it, but the line is not leading to anything. The line just <i>is</i>, which defeats the challenge I think.</td>', 'I like it, but the line is not leading to anything. The line just is, which defeats the challenge I think.', '2008-02-23 00:28:27.000000', NULL, 1),
(4508994, 648968, 90380, '<td valign="top">I like the simplicity of the two strong colours, and this does meet the challenge.</td>', 'I like the simplicity of the two strong colours, and this does meet the challenge.', '2008-02-23 00:33:59.000000', NULL, 1),
(4508995, 648231, 90074, '<td valign="top">I doesn''t have one straight leading line to it but I like how it swirls.</td>', 'I doesn''t have one straight leading line to it but I like how it swirls.', '2008-02-23 00:34:34.000000', NULL, 1),
(4508997, 648912, 90074, '<td valign="top">It''s a little to slanted but it is still a good picture.</td>', 'It''s a little to slanted but it is still a good picture.', '2008-02-23 00:35:36.000000', NULL, 1),
(4509000, 646960, 90380, '<td valign="top">I thought for a minute that the image didn''t fully load because the bottom part looks too white and straight and somehow unnatural. I like how the lines are curvy and sweeping, but they lead me out of the image rather than in.</td>', 'I thought for a minute that the image didn''t fully load because the bottom part looks too white and straight and somehow unnatural. I like how the lines are curvy and sweeping, but they lead me out of the image rather than in.', '2008-02-23 00:37:40.000000', NULL, 1),
(4509002, 647854, 90380, '<td valign="top">Nice landscape, but I don''t feel the lines are leading enough.</td>', 'Nice landscape, but I don''t feel the lines are leading enough.', '2008-02-23 00:38:59.000000', NULL, 1),
(4509014, 647405, 90380, '<td valign="top">I don''t feel the lines are prominent enough, and the border is a little strong, and there is too much noise, but don''t dispair! As an image in itself, it isn''t bad, and I like the blues.</td>', 'I don''t feel the lines are prominent enough, and the border is a little strong, and there is too much noise, but don''t dispair! As an image in itself, it isn''t bad, and I like the blues.', '2008-02-23 00:53:24.000000', NULL, 1),
(4509016, 648615, 90380, '<td valign="top">Very nice macro! Meets the challenge, but not particularly strikingly.</td>', 'Very nice macro! Meets the challenge, but not particularly strikingly.', '2008-02-23 00:54:30.000000', NULL, 1),
(4509020, 648936, 70377, '<td valign="top">I really Like this photo, Really sticks to the Subject.</td>', 'I really Like this photo, Really sticks to the Subject.', '2008-02-23 00:55:39.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4509021, 649055, 70377, '<td valign="top">Interesting, I like the Symetry...</td>', 'Interesting, I like the Symetry...', '2008-02-23 00:56:44.000000', NULL, 1),
(4509022, 648492, 90380, '<td valign="top">The colour cast is a bit too strong for me, but nice star effect.</td>', 'The colour cast is a bit too strong for me, but nice star effect.', '2008-02-23 00:56:46.000000', NULL, 1),
(4509026, 649028, 90380, '<td valign="top">Breathtaking!</td>', 'Breathtaking!', '2008-02-23 00:58:00.000000', NULL, 1),
(4509034, 647966, 90380, '<td valign="top">Yep. Meets the challenge, and it''s great! One interesting little detail is the kite up in the sky. I love this.</td>', 'Yep. Meets the challenge, and it''s great! One interesting little detail is the kite up in the sky. I love this.', '2008-02-23 00:59:45.000000', NULL, 1),
(4509039, 648744, 70377, '<td valign="top">Very Nice.  Whats at the end of the tunnel?</td>', 'Very Nice.  Whats at the end of the tunnel?', '2008-02-23 01:00:50.000000', NULL, 1),
(4509043, 648888, 70377, '<td valign="top">Interesting, I like the idea,</td>', 'Interesting, I like the idea,', '2008-02-23 01:02:33.000000', NULL, 1),
(4509048, 648318, 70377, '<td valign="top">Whats with the color cast?</td>', 'Whats with the color cast?', '2008-02-23 01:03:04.000000', NULL, 1),
(4509049, 647892, 90380, '<td valign="top">Nice macro. I like how I get the feeling that there is a warm light radiating from the centre of the flower. I guess technically, there is, but it feels like the source, and it feels warm and safe in there.</td>', 'Nice macro. I like how I get the feeling that there is a warm light radiating from the centre of the flower. I guess technically, there is, but it feels like the source, and it feels warm and safe in there.', '2008-02-23 01:03:57.000000', NULL, 1),
(4509054, 647497, 90380, '<td valign="top">Very nice photo, but I''m not sure the lines are leading quite enough.</td>', 'Very nice photo, but I''m not sure the lines are leading quite enough.', '2008-02-23 01:05:06.000000', NULL, 1),
(4509057, 647304, 70377, '<td valign="top">I do not understand this picture? Maybe not so dark next time.</td>', 'I do not understand this picture? Maybe not so dark next time.', '2008-02-23 01:05:36.000000', NULL, 1),
(4509059, 647341, 70377, '<td valign="top">wonder if it would look better by cropping some more of the bottem of the picture.</td>', 'wonder if it would look better by cropping some more of the bottem of the picture.', '2008-02-23 01:07:20.000000', NULL, 1),
(4509063, 648046, 70377, '<td valign="top">Nice shot..</td>', 'Nice shot..', '2008-02-23 01:08:23.000000', NULL, 1),
(4509064, 647732, 70377, '<td valign="top">This building is so neat, why are none of the people in focus?</td>', 'This building is so neat, why are none of the people in focus?', '2008-02-23 01:09:21.000000', NULL, 1),
(4509066, 648377, 90380, '<td valign="top">Interesting how the angle is rather disorienting, but I need something more to feast my eye on. Also, I think it would be better in monochrome to get rid of the dinginess.</td>', 'Interesting how the angle is rather disorienting, but I need something more to feast my eye on. Also, I think it would be better in monochrome to get rid of the dinginess.', '2008-02-23 01:09:44.000000', NULL, 1),
(4509067, 648492, 70377, '<td valign="top">This resembles more of a vanishing point...</td>', 'This resembles more of a vanishing point...', '2008-02-23 01:10:01.000000', NULL, 1),
(4509070, 648908, 90380, '<td valign="top">Wow, I SO want to go there! Can you please tell where it is?</td>', 'Wow, I SO want to go there! Can you please tell where it is?', '2008-02-23 01:10:50.000000', NULL, 1),
(4509074, 646818, 90380, '<td valign="top">One good thing, the rotation adds some interest, but I don''t feel the challenge is met here. The lines should be leading to a focal point, but they just radiate. If the subject was just "lines", you''d do okay.</td>', 'One good thing, the rotation adds some interest, but I don''t feel the challenge is met here. The lines should be leading to a focal point, but they just radiate. If the subject was just "lines", you''d do okay.', '2008-02-23 01:13:09.000000', NULL, 1),
(4509075, 648968, 70377, '<td valign="top">Good Quality...</td>', 'Good Quality...', '2008-02-23 01:13:53.000000', NULL, 1),
(4509078, 648215, 90380, '<td valign="top">Points for meeting the challenge! I do wish the colours were a little more saturated though, and some contrast would really perk it up.</td>', 'Points for meeting the challenge! I do wish the colours were a little more saturated though, and some contrast would really perk it up.', '2008-02-23 01:14:22.000000', NULL, 1),
(4509079, 647650, 70377, '<td valign="top">I want this picture to be better but it is just too confusing.</td>', 'I want this picture to be better but it is just too confusing.', '2008-02-23 01:15:02.000000', NULL, 1),
(4509081, 649001, 70377, '<td valign="top">Way over exposed in a large portion of this photo...</td>', 'Way over exposed in a large portion of this photo...', '2008-02-23 01:15:30.000000', NULL, 1),
(4509085, 648886, 70377, '<td valign="top">what is the subject of this photo?</td>', 'what is the subject of this photo?', '2008-02-23 01:16:49.000000', NULL, 1),
(4509086, 648333, 90380, '<td valign="top">I would like this more if it didn''t look so motion-blurry. But otherwise, I think the composition is interesting.</td>', 'I would like this more if it didn''t look so motion-blurry. But otherwise, I think the composition is interesting.', '2008-02-23 01:16:54.000000', NULL, 1),
