(4509092, 648276, 70377, '<td valign="top">Nice Shot...</td>', 'Nice Shot...', '2008-02-23 01:18:54.000000', NULL, 1),
(4509094, 648886, 90380, '<td valign="top">Yet another escalator picture where I wish I had something to look at at the top. Leading lines are supposed to lead to something..</td>', 'Yet another escalator picture where I wish I had something to look at at the top. Leading lines are supposed to lead to something..', '2008-02-23 01:19:16.000000', NULL, 1),
(4509101, 647991, 90380, '<td valign="top">I think the DOF should go all the way out to the far end because that is where the lines are leading.</td>', 'I think the DOF should go all the way out to the far end because that is where the lines are leading.', '2008-02-23 01:21:12.000000', NULL, 1),
