(4509155, 648354, 90380, '<td valign="top">Nice lighting. Looks almost like it is under water.</td>', 'Nice lighting. Looks almost like it is under water.', '2008-02-23 01:39:52.000000', NULL, 1),
(4509156, 648324, 70377, '<td valign="top">Love the snow...</td>', 'Love the snow...', '2008-02-23 01:40:22.000000', NULL, 1),
