(4509852, 648954, 48963, '<td valign="top">very very nice! 9</td>', 'very very nice! 9', '2008-02-23 13:20:10.000000', NULL, 1),
(4509857, 647879, 48963, '<td valign="top">Nicely spotted opportunity for a photo.</td>', 'Nicely spotted opportunity for a photo.', '2008-02-23 13:20:52.000000', NULL, 1),
(4509861, 648223, 48963, '<td valign="top">wow, what an interesting shot! I look forward to your explanation of this. 9</td>', 'wow, what an interesting shot! I look forward to your explanation of this. 9', '2008-02-23 13:22:55.000000', NULL, 1),
