(4515300, 648271, 88054, '<td valign="top">Great concept. Beautiful exposure.</td>', 'Great concept. Beautiful exposure.', '2008-02-25 14:05:24.000000', NULL, 1),
(4515307, 648789, 90658, '<td valign="top">There''s a lot going on in this picture.  The reflection is a nice touch.</td>', 'There''s a lot going on in this picture.  The reflection is a nice touch.', '2008-02-25 14:06:13.000000', NULL, 1),
(4515308, 648952, 88054, '<td valign="top">Clever</td>', 'Clever', '2008-02-25 14:06:14.000000', NULL, 1),
