(4521003, 648954, 4793, '<td valign="top">A beautiful shot/congratulations</td>', 'A beautiful shot/congratulations', '2008-02-27 09:31:17.000000', NULL, 0),
(4521123, 648987, 65083, '<td valign="top">I agree with Jeff the score dosen''t matter, it''s a great shot.</td>', 'I agree with Jeff the score dosen''t matter, it''s a great shot.', '2008-02-27 09:53:26.000000', NULL, 0),
(4521151, 648223, 90451, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by glad2badad:</b></div><hr/><i> A top ten finish in your first challenge.  How sweet is that?!  :-)<br/> <br/>Well done.  I look forward to seeing more of your work. </i></td></tr></table> <br/> <br/>Thank you!  Though it was a bit disheartening/nerve-racking to see my score free fall over the last day or so.  I look forward to getting a detailed critique from the DPC critic gurus.<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by levyj413:</b></div><hr/><i> Fantastic use of perspective.  Very effective illusion!<br/> <br/>So is that a statue up there? </i></td></tr></table> <br/> <br/>Sort of.  It is some installation art hanging off the glass ceiling at the Museum of Fine Arts.  Great museum, BTW. Definitely worth a visit if you''re ever in Boston.</td>', 'Originally posted by glad2badad: A top ten finish in your first challenge.  How sweet is that?!  :-) Well done.  I look forward to seeing more of your work.   Thank you!  Though it was a bit disheartening/nerve-racking to see my score free fall over the last day or so.  I look forward to getting a detailed critique from the DPC critic gurus. Originally posted by levyj413: Fantastic use of perspective.  Very effective illusion! So is that a statue up there?   Sort of.  It is some installation art hanging off the glass ceiling at the Museum of Fine Arts.  Great museum, BTW. Definitely worth a visit if you''re ever in Boston.', '2008-02-27 09:56:05.000000', NULL, 0),
(4521153, 648766, 80459, '<td valign="top">Very nice! Congrats.</td>', 'Very nice! Congrats.', '2008-02-27 09:57:10.000000', NULL, 0),
(4521175, 647597, 58452, '<td valign="top">Nice doc.  At least you didn''t carry the camera out there this time. I think you should do a SP series of yourself in various ticklish, wet, dirty, ect. situations.</td>', 'Nice doc.  At least you didn''t carry the camera out there this time. I think you should do a SP series of yourself in various ticklish, wet, dirty, ect. situations.', '2008-02-27 10:03:36.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4521182, 648271, 55005, '<td valign="top">I thought that skyline looked somewhat familiar.  :) Congrats on another beautiful photo!</td>', 'I thought that skyline looked somewhat familiar.  :) Congrats on another beautiful photo!', '2008-02-27 10:04:14.000000', NULL, 0),
(4521264, 648903, 65083, '<td valign="top">I happen to like and I don''t think it''s a bad photo.  It''s just not the eye candy people want.</td>', 'I happen to like and I don''t think it''s a bad photo.  It''s just not the eye candy people want.', '2008-02-27 10:17:15.000000', NULL, 0),
(4521268, 648944, 65083, '<td valign="top">great and it leads me to the bend and I want to see what''s around it.<br/></td>', 'great and it leads me to the bend and I want to see what''s around it.', '2008-02-27 10:19:02.000000', NULL, 0),
(4521276, 648952, 65083, '<td valign="top">As always you do great.</td>', 'As always you do great.', '2008-02-27 10:20:54.000000', NULL, 0),
(4521362, 646960, 66384, '<td valign="top">It is so funny -- not the image, but my reaction to the image. The snow is such a pure white without any detail at all, that I thought the image didn''t finish loading. I pressed the reload button on my browser a couple of times before it dawned on me that it is winter in Michigan. It is a beautiful shot, Terry. I love the soft pastel gradient of the sky.</td>', 'It is so funny -- not the image, but my reaction to the image. The snow is such a pure white without any detail at all, that I thought the image didn''t finish loading. I pressed the reload button on my browser a couple of times before it dawned on me that it is winter in Michigan. It is a beautiful shot, Terry. I love the soft pastel gradient of the sky.', '2008-02-27 10:42:29.000000', NULL, 0),
(4521383, 649007, 66384, '<td valign="top">You always come up with the most amazing designs. I love this colorful "cityscape".</td>', 'You always come up with the most amazing designs. I love this colorful "cityscape".', '2008-02-27 10:47:51.000000', NULL, 0),
(4521388, 649032, 66384, '<td valign="top">It does look like Dogwood is pointing. But what I really like about this image are the beautiful colors and bokeh.</td>', 'It does look like Dogwood is pointing. But what I really like about this image are the beautiful colors and bokeh.', '2008-02-27 10:50:05.000000', NULL, 0),
(4521399, 648954, 3724, '<td valign="top">Beautiful view.</td>', 'Beautiful view.', '2008-02-27 10:52:08.000000', NULL, 0),
(4521438, 648861, 66384, '<td valign="top">You had me fooled. I thought this was an actual baby playing in an enormous sandbox. lol The size of the cutout really messes with the perspective here -- the tiny car in the background makes the plowed field look so vast. I like the image, but I don''t really see much of a leading line since the furrows don''t really lead anywhere.</td>', 'You had me fooled. I thought this was an actual baby playing in an enormous sandbox. lol The size of the cutout really messes with the perspective here -- the tiny car in the background makes the plowed field look so vast. I like the image, but I don''t really see much of a leading line since the furrows don''t really lead anywhere.', '2008-02-27 10:58:37.000000', NULL, 0),
(4521476, 648223, 44877, '<td valign="top">Top ten on your first challenge - awesome! You should stop now for an average of 6.7 - ha. <br/> <br/>This is an amazing photo - you got a 10 from me.</td>', 'Top ten on your first challenge - awesome! You should stop now for an average of 6.7 - ha.  This is an amazing photo - you got a 10 from me.', '2008-02-27 11:04:20.000000', NULL, 0),
(4521486, 648987, 66384, '<td valign="top">This is so elegant. I love the sunlight leading up the stairs. I might like the image even better if it was symmetrical, but that might have messed up the angle of the sunlight.</td>', 'This is so elegant. I love the sunlight leading up the stairs. I might like the image even better if it was symmetrical, but that might have messed up the angle of the sunlight.', '2008-02-27 11:05:43.000000', NULL, 0),
(4521489, 648816, 44877, '<td valign="top">Hey Sarah - great finish! Love this photo and SaraR put it very well - that the leading lines don''t form the subject, which makes this such an interesting image. <br/> <br/>Congrats!!</td>', 'Hey Sarah - great finish! Love this photo and SaraR put it very well - that the leading lines don''t form the subject, which makes this such an interesting image.  Congrats!!', '2008-02-27 11:07:33.000000', NULL, 0),
(4521529, 648259, 83032, '<td valign="top">Okay, I was really stupid on this one.  I miss read the challenge and thought the "Leading Lines" were from a movie and this was my attempt at Dirty Harry.  What can I say?   It is one of my better shots....poop!</td>', 'Okay, I was really stupid on this one.  I miss read the challenge and thought the "Leading Lines" were from a movie and this was my attempt at Dirty Harry.  What can I say?   It is one of my better shots....poop!', '2008-02-27 11:25:00.000000', NULL, 0),
(4521553, 648766, 4517, '<td valign="top">Congrats on the ribbon. I also thought it was ir.</td>', 'Congrats on the ribbon. I also thought it was ir.', '2008-02-27 11:29:33.000000', NULL, 0),
(4521777, 648596, 58728, '<td valign="top">Underrated.  I think it''s brilliant.</td>', 'Underrated.  I think it''s brilliant.', '2008-02-27 12:08:31.000000', NULL, 0),
(4521786, 648080, 58728, '<td valign="top">I love this.  I gave it an 8.</td>', 'I love this.  I gave it an 8.', '2008-02-27 12:10:06.000000', NULL, 0),
(4521795, 648333, 58728, '<td valign="top">Love, love LOVE this.</td>', 'Love, love LOVE this.', '2008-02-27 12:11:04.000000', NULL, 0),
(4521801, 648954, 36999, '<td valign="top">HAHA!  Not Sammie,  but is still has that gorgeous Sammie flow to it.  congrats on the ribbon!</td>', 'HAHA!  Not Sammie,  but is still has that gorgeous Sammie flow to it.  congrats on the ribbon!', '2008-02-27 12:12:01.000000', NULL, 0),
(4521805, 649046, 58728, '<td valign="top">WHAT!?!?  I guessed this would be in the top 20 for sure.  I love it!!!  It may not have scored as high because the lines aren''t "leading" us to the subject, but I think it''s a beautiful shot.  Nicely done.</td>', 'WHAT!?!?  I guessed this would be in the top 20 for sure.  I love it!!!  It may not have scored as high because the lines aren''t "leading" us to the subject, but I think it''s a beautiful shot.  Nicely done.', '2008-02-27 12:12:42.000000', NULL, 0),
(4521814, 648071, 58728, '<td valign="top">Underrated for sure.</td>', 'Underrated for sure.', '2008-02-27 12:13:47.000000', NULL, 0),
(4521819, 648604, 58728, '<td valign="top">I think it''s perfect.</td>', 'I think it''s perfect.', '2008-02-27 12:15:16.000000', NULL, 0),
(4521821, 648820, 58728, '<td valign="top">I was your 10.  I love it.</td>', 'I was your 10.  I love it.', '2008-02-27 12:16:25.000000', NULL, 0),
(4521828, 647966, 86026, '<td valign="top">nice shot, but wwwaaaaay too sharp.. just look at the halos... I would fix that if I were you. congrats on the win.</td>', 'nice shot, but wwwaaaaay too sharp.. just look at the halos... I would fix that if I were you. congrats on the win.', '2008-02-27 12:17:38.000000', NULL, 0),
(4521843, 648992, 60862, '<td valign="top">Very nice abstract image.  I like how you used depth of field to emphasize the texture on the closer part of the blur pipe.  The background looks like a painting.  Congrats on your new personal best! :)</td>', 'Very nice abstract image.  I like how you used depth of field to emphasize the texture on the closer part of the blur pipe.  The background looks like a painting.  Congrats on your new personal best! :)', '2008-02-27 12:20:04.000000', NULL, 0),
(4521863, 648992, 7743, '<td valign="top">Love the background.  Congrats on a PB.</td>', 'Love the background.  Congrats on a PB.', '2008-02-27 12:23:57.000000', NULL, 0),
(4521875, 647966, 24454, '<td valign="top">Breeee, what a FABULOUS photo!   Congratulations on this most deserved blue!!!</td>', 'Breeee, what a FABULOUS photo!   Congratulations on this most deserved blue!!!', '2008-02-27 12:25:22.000000', NULL, 0),
(4521923, 648987, 61651, '<td valign="top">Fantastic in b/w - personally I might have gone for more of a crop at the top, so the white sky parts up there aren''t competing for attention with the doorway whites.</td>', 'Fantastic in b/w - personally I might have gone for more of a crop at the top, so the white sky parts up there aren''t competing for attention with the doorway whites.', '2008-02-27 12:32:34.000000', NULL, 0),
(4521940, 648952, 61651, '<td valign="top">Crazy wild - leading lines all over the place.  I like the title marriage with the image, great catch!</td>', 'Crazy wild - leading lines all over the place.  I like the title marriage with the image, great catch!', '2008-02-27 12:34:51.000000', NULL, 0),
(4521957, 648971, 61651, '<td valign="top">This is a refreshingly creative take on the challenge theme - I do think the yellow wall area detracts a bit from the full vertigo effect, if only because it is a contrasting color, perhaps - maybe there would have been a way to capture the door with the same angles to the lines, without including the side wall?</td>', 'This is a refreshingly creative take on the challenge theme - I do think the yellow wall area detracts a bit from the full vertigo effect, if only because it is a contrasting color, perhaps - maybe there would have been a way to capture the door with the same angles to the lines, without including the side wall?', '2008-02-27 12:38:38.000000', NULL, 0),
(4521985, 648757, 61651, '<td valign="top">Leading lines work well for me here - and I like how you placed the most light area on the left third of the shot, you get a sense of expansiveness from all that light-going-to-black on the right, and sets off the "main" area well, even better, I think, than the cropped version.  I see this as, beyond the meet-the-challenge aspect, a study of light and shadows, so I''m not concerned too much about loss of detail.  I suppose I should have voted this challenge. :(</td>', 'Leading lines work well for me here - and I like how you placed the most light area on the left third of the shot, you get a sense of expansiveness from all that light-going-to-black on the right, and sets off the "main" area well, even better, I think, than the cropped version.  I see this as, beyond the meet-the-challenge aspect, a study of light and shadows, so I''m not concerned too much about loss of detail.  I suppose I should have voted this challenge. :(', '2008-02-27 12:43:35.000000', NULL, 0),
(4522002, 649032, 61651, '<td valign="top">Dogwood misdirection :)  The pointing arm is leading my eye to that burst of bokeh in the top right.  Nicely subtle, though not good for your score, I guess. ;)</td>', 'Dogwood misdirection :)  The pointing arm is leading my eye to that burst of bokeh in the top right.  Nicely subtle, though not good for your score, I guess. ;)', '2008-02-27 12:46:20.000000', NULL, 0),
(4522137, 647966, 68514, '<td valign="top">Terrific. A great shot for a great blue. Congrats.</td>', 'Terrific. A great shot for a great blue. Congrats.', '2008-02-27 13:20:46.000000', NULL, 0),
(4522153, 648766, 68514, '<td valign="top">A nice perspective and a good BW job. Congrats on red.</td>', 'A nice perspective and a good BW job. Congrats on red.', '2008-02-27 13:24:23.000000', NULL, 0),
(4522219, 648767, 68586, '<td valign="top">Congrats on your top 10 finish ! <br/> <br/>Good to see you on the front page :- )</td>', 'Congrats on your top 10 finish !  Good to see you on the front page :- )', '2008-02-27 13:51:21.000000', NULL, 0),
(4522235, 648766, 25166, '<td valign="top">Can we have a witch-hunt to establish who gave this shot a score of 1,2 or 4? I don''t understand how people can''t be more objective. A great photograph and deserved ribbon winner!</td>', 'Can we have a witch-hunt to establish who gave this shot a score of 1,2 or 4? I don''t understand how people can''t be more objective. A great photograph and deserved ribbon winner!', '2008-02-27 13:56:56.000000', NULL, 0),
