(4522242, 648992, 67258, '<td valign="top">Jamie, congratulations on a new PB - your persistence and end endeavour are paying dividends!</td>', 'Jamie, congratulations on a new PB - your persistence and end endeavour are paying dividends!', '2008-02-27 13:58:38.000000', NULL, 0),
