(4524939, 649008, 29513, '<td valign="top">Thanks for all the comments and suggestions.<br/> <br/>I was going for the line of the hand and the lines in the shirt as leading lines.<br/></td>', 'Thanks for all the comments and suggestions. I was going for the line of the hand and the lines in the shirt as leading lines.', '2008-02-28 10:46:53.000000', NULL, 0),
(4525216, 646688, 66635, '<td valign="top">Love the lighting.  Love this series.</td>', 'Love the lighting.  Love this series.', '2008-02-28 12:40:10.000000', NULL, 0),
(4525412, 647966, 88698, '<td valign="top">Wow!! What a great shot. I love the lighting, the composition and the leading lines but especially the thinking that was way outside the box. Congrats on a blue. Well deserved.</td>', 'Wow!! What a great shot. I love the lighting, the composition and the leading lines but especially the thinking that was way outside the box. Congrats on a blue. Well deserved.', '2008-02-28 13:53:52.000000', NULL, 0),
(4525535, 647966, 40718, '<td valign="top">This is a great shot Brianna.  Well worthy of blue.</td>', 'This is a great shot Brianna.  Well worthy of blue.', '2008-02-28 15:15:25.000000', NULL, 0),
(4525755, 648271, 3554, '<td valign="top">Great work! Underrated in my opinion. :)</td>', 'Great work! Underrated in my opinion. :)', '2008-02-28 16:44:25.000000', NULL, 0),
(4525857, 648080, 18450, '<td valign="top">Sorry bout the DQ Jo. This is an intriguing shot. Mystery and mischief in the expression on her face. Nice composition and I feel that the editing really suits the shot!</td>', 'Sorry bout the DQ Jo. This is an intriguing shot. Mystery and mischief in the expression on her face. Nice composition and I feel that the editing really suits the shot!', '2008-02-28 17:12:07.000000', NULL, 0),
